import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r}from"./chunks/OFF.BrU7kQE-.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/M-S-SW8c.OZF8VB_x.js";import{_ as o,o as n,c as s,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Smartwatches","description":"","frontmatter":{},"headers":[],"relativePath":"smartwatch/smartwatch.md","filePath":"smartwatch/smartwatch.md"}'),c={name:"smartwatch/smartwatch.md"};function d(h,a,p,m,b,f){return n(),s("div",null,[...a[0]||(a[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Smart Watch Features</p></div><h2 id="xdrip-direct-integration" tabindex="-1">xDrip direct integration <a class="header-anchor" href="#xdrip-direct-integration" aria-label="Permalink to &quot;xDrip direct integration&quot;">​</a></h2><p>xDrip offers a wide range of smartwatch support.</p><h3 id="android-wear-integration" tabindex="-1"><a href="./wear.html">Android Wear Integration</a> <a class="header-anchor" href="#android-wear-integration" aria-label="Permalink to &quot;[Android Wear Integration](./wear)&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Android Wear Integration</p></div><p>You&#39;ll find the most complete integration in Wear OS watches as they are running a part of the xDrip app locally.</p><p>The wear extension of xDrip is not under development anymore.</p><p>If you need more watchfaces or customizations you can use <a href="https://github.com/FreDiabetics/xDrip--Tasker-Tizen-Watchface-Integration/blob/master/README.md" target="_blank" rel="noreferrer">Tasker</a> (but not as a standalone collector).</p><h3 id="pebble-integration" tabindex="-1"><a href="./pebble.html">Pebble Integration</a> <a class="header-anchor" href="#pebble-integration" aria-label="Permalink to &quot;[Pebble Integration](./pebble)&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Pebble Integration</p></div><p>Pebble smartwatch use is a historic milestone of CGM in the Cloud. The original Pebble watches were discontinued in 2016 when Pebble was bought by Fitbit (their resources have moved to archives and <a href="https://rebble.io/" target="_blank" rel="noreferrer">rebble.io</a>). New Pebble models were relaunched in 2025: xDrip supports both, see <a href="./pebble.html">Pebble Integration</a>.</p><h3 id="amazfit-sync-service" tabindex="-1"><a href="https://crazyinfo.de/2018/07/25/xdrip-smartwatch-widget-fuer-amazfit-pace-stratos/" target="_blank" rel="noreferrer">AmazFit Sync Service</a> <a class="header-anchor" href="#amazfit-sync-service" aria-label="Permalink to &quot;[AmazFit Sync Service](https://crazyinfo.de/2018/07/25/xdrip-smartwatch-widget-fuer-amazfit-pace-stratos/)&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">AmazFit Sync Service</p></div><p>AmazFit was used only for Pace and Stratos models.<br><strong>You cannot use this feature for other AmazFit watches.</strong></p><h3 id="bluejay-watch" tabindex="-1"><a href="./bluejay.html">BlueJay Watch</a> <a class="header-anchor" href="#bluejay-watch" aria-label="Permalink to &quot;[BlueJay Watch](./bluejay)&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch</p></div><p>BlueJay is an incredible companion of your Dexcom sensor, with or without xDrip, with or without phone.</p><h3 id="lefun-band" tabindex="-1"><a href="https://www.lefunsmart.com/collections/smartwatches" target="_blank" rel="noreferrer">LeFun Band</a> <a class="header-anchor" href="#lefun-band" aria-label="Permalink to &quot;[LeFun Band](https://www.lefunsmart.com/collections/smartwatches)&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">LeFun Band</p></div><p>LeFun band integration was an early implementation for smartbands, best if used in mmol/l.<br> Unless you still own a LeFun W3, F3, F3S, F11 or F12 band this is not of any use now.</p><h3 id="miband" tabindex="-1"><a href="./miband.html">MiBand</a> <a class="header-anchor" href="#miband" aria-label="Permalink to &quot;[MiBand](./miband)&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">MiBand</p></div><p>MiBand integration is the result of the huge work of <a href="https://bigdigital.home.blog/" target="_blank" rel="noreferrer">Artem</a>.<br> Many smartwatches and smartbands are now supported using the companion app WatchDrip+.</p><div class="info custom-block"><p class="custom-block-title">Disable MiBand in xDrip if you use WatchDrip+</p><div class="admonition xdripitem"><p class="admonition-title">Use MiBand Band <span class="symbol"><img src="'+r+'" style="zoom:75%;"></span></p></div></div><h2 id="smartwatch-sensors" tabindex="-1">Smartwatch Sensors <a class="header-anchor" href="#smartwatch-sensors" aria-label="Permalink to &quot;Smartwatch Sensors&quot;">​</a></h2><p>xDrip can use supported smartwatch sensors.</p><div class="admonition xdripitem"><p class="admonition-title">Use Health data <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>xDrip can request the heartbeat sensor to activate and you can smooth that graph.</p><div class="admonition xdripitem"><p class="admonition-title">Heart Rate Sensor <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>When available you can let xDrip collect health data like heartrate and steps.</p><p>Two additional icons will appear on the main view, and if enabled, graphic representations:</p><ol><li>A dark blue graph for heartrate</li><li>A light cyan cloud line for steps</li></ol><img src="'+i+'" style="zoom:75%;"><h2 id="other-smartwatches" tabindex="-1">Other smartwatches <a class="header-anchor" href="#other-smartwatches" aria-label="Permalink to &quot;Other smartwatches&quot;">​</a></h2><p>More smartwatches and devices can receive data from xDrip even if they are not directly integrated in the app.</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>In order to have xDrip send data you need to enable xDrip <a href="./../use/interapp.html#web-service">web service</a>.</p></div><h3 id="android-wear" tabindex="-1">Android Wear <a class="header-anchor" href="#android-wear" aria-label="Permalink to &quot;Android Wear&quot;">​</a></h3><p><a href="https://github.com/pachi81/GlucoDataHandler" target="_blank" rel="noreferrer">GlucoDataHandler</a> accepts xDrip as a data source. The app is available in <a href="https://play.google.com/store/apps/details?id=de.michelinside.glucodatahandler" target="_blank" rel="noreferrer">Google Play store</a>.</p><h3 id="android-auto" tabindex="-1">Android Auto <a class="header-anchor" href="#android-auto" aria-label="Permalink to &quot;Android Auto&quot;">​</a></h3><p><a href="https://github.com/pachi81/GlucoDataAuto" target="_blank" rel="noreferrer">GlucoDataAuto</a> is the Android Auto extension of GlucoDataHandler.</p><h3 id="fitbit" tabindex="-1">Fitbit <a class="header-anchor" href="#fitbit" aria-label="Permalink to &quot;Fitbit&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Google is discontinuing Sense/Ionic/Versa</p><p>Consider that these products will be end of life in the near future.</p></div><div class="warning custom-block"><p class="custom-block-title">Not available for EU users</p><p>Google has <a href="https://support.google.com/fitbit/answer/14237121?hl=en" target="_blank" rel="noreferrer">removed</a> the possibility since June 2024. Installed watchfaces are not impacted but new users can&#39;t install custom watchfaces anymore. You need to use a VPN as a workaround.</p></div><div class="warning custom-block"><p class="custom-block-title">Android 9 and below</p><p>Android users with a version below 10 need to downgrade the Fitbit app to a previous version like 3.58 and disable automatic updates. You can find it in <a href="https://fitbit.en.aptoide.com/versions" target="_blank" rel="noreferrer">Aptoide</a> and other apk hosting servers.</p></div><h5 id="glance" tabindex="-1"><a href="https://gallery.fitbit.com/details/7b5d9822-7e8e-41f9-a2a7-e823548c001c" target="_blank" rel="noreferrer">Glance</a> <a class="header-anchor" href="#glance" aria-label="Permalink to &quot;[Glance](https://gallery.fitbit.com/details/7b5d9822-7e8e-41f9-a2a7-e823548c001c)&quot;">​</a></h5><p>Ionic/Sense/Versa/Versa 2/Versa 3/Versa 4/Versa Lite</p><p><a href="https://glancewatchface.com/" target="_blank" rel="noreferrer">Web site</a></p><h5 id="sentinel" tabindex="-1"><a href="https://gallery.fitbit.com/developer/b50ac7f5-b932-441a-be18-e258b17c736b" target="_blank" rel="noreferrer">Sentinel</a> <a class="header-anchor" href="#sentinel" aria-label="Permalink to &quot;[Sentinel](https://gallery.fitbit.com/developer/b50ac7f5-b932-441a-be18-e258b17c736b)&quot;">​</a></h5><p>Sentinel Elite for Sense/Versa 3<br> Sentinel Pro for Ionic/Versa/Versa 2/Versa Lite</p><p>Facebook group: <a href="https://www.facebook.com/groups/3185325128159614" target="_blank" rel="noreferrer">Sentinel</a></p><h5 id="marclock" tabindex="-1"><a href="https://gallery.fitbit.com/details/9eacf714-5b23-40c8-9621-ded74bd9edf9" target="_blank" rel="noreferrer">Marclock</a> <a class="header-anchor" href="#marclock" aria-label="Permalink to &quot;[Marclock](https://gallery.fitbit.com/details/9eacf714-5b23-40c8-9621-ded74bd9edf9)&quot;">​</a></h5><p>Ionic/Sense/Versa/Versa 2/Versa Lite</p><p><a href="https://github.com/cramis1/Marclock-with-CGM-weather/blob/master/README.md" target="_blank" rel="noreferrer">Instructions</a></p><h5 id="analog-cgm" tabindex="-1"><a href="https://gallery.fitbit.com/details/4d7b46b1-aaba-49b4-aa10-183321014dd3" target="_blank" rel="noreferrer">Analog CGM</a> <a class="header-anchor" href="#analog-cgm" aria-label="Permalink to &quot;[Analog CGM](https://gallery.fitbit.com/details/4d7b46b1-aaba-49b4-aa10-183321014dd3)&quot;">​</a></h5><h5 id="orbits-ns" tabindex="-1"><a href="https://gallery.fitbit.com/details/44de5c81-b77c-4f90-baa8-38f3e3d28695" target="_blank" rel="noreferrer">Orbits NS</a> <a class="header-anchor" href="#orbits-ns" aria-label="Permalink to &quot;[Orbits NS](https://gallery.fitbit.com/details/44de5c81-b77c-4f90-baa8-38f3e3d28695)&quot;">​</a></h5><h5 id="radial-cgm" tabindex="-1"><a href="https://gallery.fitbit.com/details/0173730e-5381-4495-bc6e-6ec93c8df029" target="_blank" rel="noreferrer">Radial CGM</a> <a class="header-anchor" href="#radial-cgm" aria-label="Permalink to &quot;[Radial CGM](https://gallery.fitbit.com/details/0173730e-5381-4495-bc6e-6ec93c8df029)&quot;">​</a></h5><p>Ionic/Versa/Versa 2/Versa Lite/Versa 3/Sense</p><h3 id="samsung-gear" tabindex="-1">Samsung Gear <a class="header-anchor" href="#samsung-gear" aria-label="Permalink to &quot;Samsung Gear&quot;">​</a></h3><p><a href="https://play.google.com/store/apps/details?id=sk.trupici.g_watch" target="_blank" rel="noreferrer">G-Watch</a> is the easiest way to perform this. See the <a href="https://github.com/trupici/G-Watch-Wear/wiki" target="_blank" rel="noreferrer">wiki</a>.</p><p>You can also use <a href="https://github.com/FreDiabetics/xDrip--Tasker-Tizen-Watchface-Integration/blob/master/README.md" target="_blank" rel="noreferrer">Tasker</a> to display xDrip data on your Samsung Gear watch.</p><h3 id="garmin" tabindex="-1">Garmin <a class="header-anchor" href="#garmin" aria-label="Permalink to &quot;Garmin&quot;">​</a></h3><p>Many Garmin watchfaces are available, check your model is supported.</p><p>By <a href="https://apps.garmin.com/en-US/developer/e985e9ec-bcf6-4aef-bfe9-77c1c93fc854/apps" target="_blank" rel="noreferrer">Horsetooth</a></p><p>By <a href="https://apps.garmin.com/en-US/developer/f9420c47-810f-47ac-a7dd-9fa7b8ecd22d/apps" target="_blank" rel="noreferrer">andreas-may</a></p><p>By <a href="https://apps.garmin.com/en-US/developer/b2d30711-2708-4f3a-8e83-009c16d07081/apps" target="_blank" rel="noreferrer">John_</a></p><p>By <a href="https://apps.garmin.com/en-US/developer/b61690c3-5e5c-4c4e-afe9-434db16542a9/apps" target="_blank" rel="noreferrer">Roboleo1010</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',68)])])}const _=o(c,[["render",d]]);export{v as __pageData,_ as default};
